public class CuentaBancaria {
    String titular;
    double saldo;

    void depositar(double monto) {
        saldo += monto;
    }

    void mostrarInfo() {
        System.out.println(titular + " | Balance: $" + saldo);
    }

    public static void main(String[] args) {
        CuentaBancaria c1 = new CuentaBancaria();
        c1.titular = "María";
        c1.saldo = 1000;
        c1.depositar(500);
        c1.mostrarInfo();
    }
}

