public class Libro {
    static int totalLibros = 0;
    String titulo;
    String autor;
    boolean disponible;

    Libro(String titulo, String autor) {
        this.titulo = titulo;
        this.autor = autor;
        this.disponible = true;
        totalLibros++;
    }

    void prestar() {
        if (disponible) {
            disponible = false;
            System.out.println("\"" + titulo + "\" borrowed");
        } else {
            System.out.println("\"" + titulo + "\" not available");
        }
    }

    static int getTotalLibros() {
        return totalLibros;
    }

    void mostrar() {
        System.out.println(titulo + " - " + autor + (disponible ? " [Available]" : " [Borrowed]"));
    }

    public static void main(String[] args) {
        Libro l1 = new Libro("Java Básico", "Juan");
        Libro l2 = new Libro("POO", "Ana");
        Libro l3 = new Libro("Algoritmos", "Luis");
        l1.prestar();
        l1.mostrar();
        l2.mostrar();
        System.out.println("Total: " + Libro.getTotalLibros());
    }
}

